        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var briefKeys = ['brief_r1', 'brief_r2', 'brief_r3', 'brief_r4'];
            var briefEl = document.getElementById('briefingText');
            if (briefEl && window.mySimulation) briefEl.innerHTML = window.mySimulation.t(briefKeys[idx]);

            var titleKeys = ['r1_title', 'r2_title', 'r3_title', 'r4_title'];
            var titleEl = document.getElementById('roundTitle');
            if (titleEl && window.mySimulation) titleEl.innerHTML = window.mySimulation.t(titleKeys[idx]);

            for (var i = 0; i < this.ROUNDS.length; i++) {
                var panel = document.getElementById(this.ROUNDS[i].panel);
                if (panel) panel.style.display = (i === idx && period <= this.ROUNDS.length) ? 'block' : 'none';
            }
        }
